package com.example.demo.accounting;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.http.*;
import java.util.*;
import java.io.IOException;

@RestController @RequestMapping("/api/accounting") @RequiredArgsConstructor
@PreAuthorize("hasAnyRole('PLATFORM_SUPER_ADMIN','ENTERPRISE_ADMIN','BRANCH_ADMIN','ACCOUNTANT','COMPANY_ADMIN','ACCOUNTS_MANAGER','CEO','SUPER_ADMIN','ACCOUNT_MANAGER','COMPANY_MANAGER') and hasAuthority('payroll:view') and !hasAuthority('POSITION_PAYROLL_EXCLUDED')")
public class AccountingController {
 private final AccountingService service;private final AccountingExportService exports;
 @GetMapping("/salary") public Map<String,Object> salary(@RequestHeader("X-Company-Id") long companyId,@RequestParam String month,@RequestParam(defaultValue="false") boolean organization,@RequestParam(required=false) List<Long> employeeIds){return service.salary(companyId,month,organization,employeeIds);}
 @GetMapping("/salary.xlsx") public ResponseEntity<byte[]> salaryExcel(@RequestHeader("X-Company-Id") long companyId,@RequestParam String month,@RequestParam(defaultValue="false") boolean organization,@RequestParam(required=false) List<Long> employeeIds)throws IOException{return file(exports.salary(companyId,month,organization,employeeIds),"salary-sheet.xlsx");}
 @GetMapping("/ledger") public Map<String,Object> ledger(@RequestHeader("X-Company-Id") long companyId,@RequestParam String month,@RequestParam(defaultValue="false") boolean organization,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="50") int size){return service.ledger(companyId,month,organization,page,size);}
 @GetMapping("/ledger.xlsx") public ResponseEntity<byte[]> ledgerExcel(@RequestHeader("X-Company-Id") long companyId,@RequestParam String month,@RequestParam(defaultValue="false") boolean organization)throws IOException{return file(exports.ledger(companyId,month,organization),"accounting-ledger.xlsx");}
 @GetMapping("/accounts") public List<Map<String,Object>> accounts(@RequestHeader("X-Company-Id") long companyId){return service.accounts(companyId);}
 @PostMapping("/accounts") @PreAuthorize("hasAnyRole('PLATFORM_SUPER_ADMIN','ENTERPRISE_ADMIN','BRANCH_ADMIN','ACCOUNTANT','COMPANY_ADMIN','ACCOUNTS_MANAGER','CEO','SUPER_ADMIN','ACCOUNT_MANAGER','COMPANY_MANAGER') and hasAuthority('payroll:view') and !hasAuthority('POSITION_PAYROLL_EXCLUDED') and hasAuthority('payroll:approve')") public Map<String,String> createAccount(@RequestHeader("X-Company-Id") long companyId,@RequestBody Map<String,String> request){service.createAccount(companyId,request.get("code"),request.get("name"),request.get("type"));return Map.of("message","Account created");}
 @GetMapping("/deduction-mappings") public List<Map<String,Object>> mappings(@RequestHeader("X-Company-Id") long companyId){return service.mappings(companyId);}
 @PutMapping("/deduction-mappings") @PreAuthorize("hasAnyRole('PLATFORM_SUPER_ADMIN','ENTERPRISE_ADMIN','BRANCH_ADMIN','ACCOUNTANT','COMPANY_ADMIN','ACCOUNTS_MANAGER','CEO','SUPER_ADMIN','ACCOUNT_MANAGER','COMPANY_MANAGER') and hasAuthority('payroll:view') and !hasAuthority('POSITION_PAYROLL_EXCLUDED') and hasAuthority('payroll:approve')") public Map<String,String> map(@RequestHeader("X-Company-Id") long companyId,@RequestBody AccountingService.MappingRequest request){service.mapDeduction(companyId,request);return Map.of("message","Deduction classification saved");}
 @PostMapping("/payroll/post") @PreAuthorize("hasAnyRole('PLATFORM_SUPER_ADMIN','ENTERPRISE_ADMIN','BRANCH_ADMIN','ACCOUNTANT','COMPANY_ADMIN','ACCOUNTS_MANAGER','CEO','SUPER_ADMIN','ACCOUNT_MANAGER','COMPANY_MANAGER') and hasAuthority('payroll:view') and !hasAuthority('POSITION_PAYROLL_EXCLUDED') and hasAuthority('payroll:approve')") public Map<String,Object> post(@RequestHeader("X-Company-Id") long companyId,@RequestBody AccountingService.PayrollPostRequest request){return service.postPayroll(companyId,request);}
 @PostMapping("/payroll/payment") @PreAuthorize("hasAnyRole('PLATFORM_SUPER_ADMIN','ENTERPRISE_ADMIN','BRANCH_ADMIN','ACCOUNTANT','COMPANY_ADMIN','ACCOUNTS_MANAGER','CEO','SUPER_ADMIN','ACCOUNT_MANAGER','COMPANY_MANAGER') and hasAuthority('payroll:view') and !hasAuthority('POSITION_PAYROLL_EXCLUDED') and hasAuthority('payroll:approve')") public Map<String,Object> payment(@RequestHeader("X-Company-Id") long companyId,@RequestBody AccountingService.PaymentRequest request){return service.recordPayment(companyId,request);}
 @PutMapping("/payroll/{id}/review") @PreAuthorize("hasAnyRole('PLATFORM_SUPER_ADMIN','ENTERPRISE_ADMIN','BRANCH_ADMIN','ACCOUNTANT','COMPANY_ADMIN','ACCOUNTS_MANAGER','CEO','SUPER_ADMIN','ACCOUNT_MANAGER','COMPANY_MANAGER') and hasAuthority('payroll:view') and !hasAuthority('POSITION_PAYROLL_EXCLUDED') and hasAuthority('payroll:approve')") public Map<String,String> review(@RequestHeader("X-Company-Id") long companyId,@PathVariable long id,@RequestBody AccountingService.ReviewRequest request){service.reviewPayroll(companyId,id,request);return Map.of("message","Payroll classification reviewed");}
 @PostMapping("/journals") @PreAuthorize("hasAnyRole('PLATFORM_SUPER_ADMIN','ENTERPRISE_ADMIN','BRANCH_ADMIN','ACCOUNTANT','COMPANY_ADMIN','ACCOUNTS_MANAGER','CEO','SUPER_ADMIN','ACCOUNT_MANAGER','COMPANY_MANAGER') and hasAuthority('payroll:view') and !hasAuthority('POSITION_PAYROLL_EXCLUDED') and hasAuthority('payroll:approve')") public Map<String,Long> journal(@RequestHeader("X-Company-Id") long companyId,@RequestBody AccountingService.JournalRequest request){return Map.of("id",service.journal(companyId,request));}
 @PostMapping("/journals/{id}/reverse") @PreAuthorize("hasAnyRole('PLATFORM_SUPER_ADMIN','ENTERPRISE_ADMIN','BRANCH_ADMIN','ACCOUNTANT','COMPANY_ADMIN','ACCOUNTS_MANAGER','CEO','SUPER_ADMIN','ACCOUNT_MANAGER','COMPANY_MANAGER') and hasAuthority('payroll:view') and !hasAuthority('POSITION_PAYROLL_EXCLUDED') and hasAuthority('payroll:approve')") public Map<String,Long> reverse(@RequestHeader("X-Company-Id") long companyId,@PathVariable long id,@RequestBody AccountingService.ReverseRequest request){return Map.of("id",service.reverse(companyId,id,request));}
 private ResponseEntity<byte[]> file(byte[] bytes,String name){return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+name+"\"").contentType(MediaType.parseMediaType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")).body(bytes);}
}
